import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.joining;import static java.util.stream.Collectors.toList;class Result {public static List<Integer> gradingStudents(List<Integer> grades) {List<Integer> result = new ArrayList<>();for (int grade : grades) {if (grade < 38) {result.add(grade);} else {int nextMultipleOf5 = ((grade / 5) + 1) * 5;if (nextMultipleOf5 - grade < 3) {result.add(nextMultipleOf5);} else {result.add(grade);}}}return result;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));String outputPath = System.getenv("OUTPUT_PATH");BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(outputPath != null ? outputPath : FileDescriptor.out.toString()));int gradesCount = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> grades = IntStream.range(0, gradesCount).mapToObj(i -> {try {return bufferedReader.readLine().replaceAll("\\s+$", "");} catch (IOException ex) {throw new RuntimeException(ex);}}).map(String::trim).map(Integer::parseInt).collect(toList());List<Integer> result = Result.gradingStudents(grades);bufferedWriter.write(result.stream().map(Object::toString).collect(joining("\n")) + "\n");bufferedReader.close();bufferedWriter.close();}}